server=r'''from http.server import BaseHTTPRequestHandler,HTTPServer
from pathlib import Path
import hashlib,html,json,os
ROOT=Path('/app/repository'); REL=Path('/app/release')
def token_hash(v): return hashlib.sha256(v.encode()).hexdigest()
def record(scope):
    return next(x for x in json.loads(REL.joinpath('registry.json').read_text())['authorizations'] if x['scope']==scope)
class H(BaseHTTPRequestHandler):
    def auth(self,scope):
        r=record(scope); h=self.headers.get('Authorization','')
        return r['active'] and h.startswith('Bearer ') and token_hash(h[7:])==r['token_sha256']
    def do_POST(self):
        if not self.path.startswith('/publish/') or not self.auth('publish:vectorops:0.1.0'):
            self.send_response(401); self.end_headers(); return
        name=os.path.basename(self.path); allowed=name.startswith('vectorops-0.1.0')
        if not allowed: self.send_response(403); self.end_headers(); return
        body=self.rfile.read(int(self.headers.get('Content-Length','0'))); ROOT.joinpath('packages',name).write_bytes(body)
        if name.endswith('.whl'): ROOT.joinpath('simple/vectorops/index.html').write_text('<a href=../../packages/'+html.escape(name)+'>'+html.escape(name)+'</a>\n')
        self.send_response(201); self.end_headers(); self.wfile.write(b'accepted')
    def do_GET(self):
        if self.path=='/admin/health':
            if not self.auth('admin:health:read'): self.send_response(401); self.end_headers(); return
            self.send_response(200); self.end_headers(); self.wfile.write(b'repository-ready'); return
        if self.path=='/admin/authorize':
            if not self.auth('publish:vectorops:0.1.0'): self.send_response(401); self.end_headers(); return
            r=record('publish:vectorops:0.1.0'); self.send_response(200); self.end_headers(); self.wfile.write(('authorization '+r['id']+' scope='+r['scope']+' decision=allow').encode()); return
        p=ROOT/self.path.lstrip('/')
        if p.is_dir(): p=p/'index.html'
        if not p.is_file(): self.send_response(404); self.end_headers(); return
        self.send_response(200); self.send_header('Content-Type','text/html' if p.suffix=='.html' else 'application/octet-stream'); self.end_headers(); self.wfile.write(p.read_bytes())
    def log_message(self,*args): pass
HTTPServer(('127.0.0.1',8080),H).serve_forever()
'''
p.joinpath('repository_server.py').write_text(server)
